$p = 'app\src\main\res\values-fr\strings.xml' if (-not (Test-Path $p)) { Write-Output "File not found: $p"; exit 1 } Write-Output "Inspecting file: $p" $lines = [System.IO.File]::ReadAllLines($p) for ($i=0; $i -lt $lines.Length; $i++) { $line = $lines[$i] $bad = @() for ($j=0; $j -lt $line.Length; $j++) { $ch = $line[$j] $code = [int][char]$ch # detect control bytes (<32 except tab/newline/CR), non-ASCII (>127), and literal backslash if (($code -lt 32 -and $code -ne 9 -and $code -ne 10 -and $code -ne 13) -or $code -gt 127) { $bad += ('0x{0:X2}' -f $code) } if ($ch -eq '') { $bad += 'BACKSLASH' } } if ($bad.Count -gt 0) { Write-Output "LINE $($i+1): $line" Write-Output " BAD BYTES: $($bad -join ', ')" } } Write-Output "Inspection complete."